module course_selection (\n    input wire        clk,          \n    input wire        rst_n,        \n    input wire        start,        \n    input wire [3:0]  k,            \n    input wire [7:0]  diff [0:7],   \n    input wire [7:0]  is_level2,    \n    input wire [2:0]  prereq_idx[0:7], \n    output reg  [15:0] result,       \n    output reg         done          \n);\n\n    // State declarations\n    localparam [2:0] IDLE       = 3'd0;\n    localparam [2:0] INIT_MIN   = 3'd1;\n    localparam [2:0] LOOP       = 3'd2;\n    localparam [2:0] CHECK      = 3'd3;\n    localparam [2:0] UPDATE     = 3'd4;\n    localparam [2:0] INCREMENT  = 3'd5;\n    localparam [2:0] DONE_STATE = 3'd6;\n    \n    reg [2:0] state;\n    reg [7:0] mask;              \n    reg [15:0] min_sum;          \n    reg [3:0] current_popcount;  \n    reg [15:0] current_sum;      \n    reg current_valid;           \n    integer i;                    \n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            mask <= 8'd0;\n            min_sum <= 16'hFFFF;\n            result <= 16'd0;\n            done <= 1'b0;\n            current_popcount <= 4'd0;\n            current_sum <= 16'd0;\n            current_valid <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT_MIN;\n                    end\n                end\n                \n                INIT_MIN: begin\n                    min_sum <= 16'hFFFF;\n                    mask <= 8'd0;\n                    state <= LOOP;\n                end\n                \n                LOOP: begin\n                    current_valid <= 1'b1;\n                    current_popcount <= 4'd0;\n                    current_sum <= 16'd0;\n                    \n                    for (i = 0; i < 8; i = i + 1) begin\n                        if (mask[i]) begin\n                            current_popcount <= current_popcount + 4'd1;\n                            current_sum <= current_sum + diff[i];\n                            \n                            // Validate prerequisites\n                            if (is_level2[i]) begin\n                                if (!mask[prereq_idx[i]]) begin\n                                    current_valid <= 1'b0;\n                                end\n                            end\n                        end\n                    end\n                    state <= CHECK;\n                end\n                \n                CHECK: begin\n                    if (current_valid && (current_popcount == k)) begin\n                        if (current_sum < min_sum) begin\n                            state <= UPDATE;\n                        end else begin\n                            state <= INCREMENT;\n                        end\n                    end else begin\n                        state <= INCREMENT;\n                    end\n                end\n                \n                UPDATE: begin\n                    min_sum <= current_sum;\n                    state <= INCREMENT;\n                end\n                \n                INCREMENT: begin\n                    mask <= mask + 8'd1;\n                    if (mask == 8'hFF) begin\n                        state <= DONE_STATE;\n                    end else begin\n                        state <= LOOP;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    result <= min_sum;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule